import * as api from '/atlas-api.js';
import {THEMES,FILTERS} from '/data.js';
const root=document.querySelector('#workspace');
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let section='content',contents=[],users=[],activity=null,selected=null,isNew=false,busy=false,identity,toastTimer;
const statusLabel={draft:'草稿',published:'已发布',archived:'已下架'};
function status(text,error=false){const node=document.querySelector('#workspace-status');node.textContent=text;node.hidden=false;node.classList.toggle('workspace-error',error);clearTimeout(toastTimer);toastTimer=setTimeout(()=>{node.hidden=true;},7000);}
function draft(){return{id:crypto.randomUUID(),slug:'',content_type:'exercise',title:'',english_title:'',summary:'',aliases:[],review_status:'needs-review',theme_links:[],discipline_ids:['strength'],equipment_ids:[],primary_muscle_ids:[],secondary_muscle_ids:[],details:{},display_order:100,publication_status:'draft',media:[]};}
function checkboxGroup(name,options,values){return options.map(option=>`<label><input type="checkbox" name="${name}" value="${esc(option.id)}" ${(values??[]).includes(option.id)?'checked':''}>${esc(option.name)}</label>`).join('');}
function contentEditor(){if(!selected)return '<section class="workspace-card"><h2>内容与发布</h2><p>选择内容进行编辑，或建立一份草稿。媒体上传完成后才能发布动作资料。</p><button class="button primary" data-action="new">新建草稿 ＋</button></section>';return `<section class="workspace-card"><div class="workspace-row"><h2>${isNew?'新建草稿':'编辑内容'}</h2><span class="workspace-pill">${statusLabel[selected.publication_status]}</span></div>${selected.publication_status==='published'?'<div class="workspace-warning">此内容已经发布，保存文字修改会立即更新公开页面。需要审核修改时，请先转为草稿。</div>':''}<form id="content-form"><div class="workspace-two"><label>名称<input name="title" maxlength="150" required value="${esc(selected.title)}"></label><label>英文名称<input name="english_title" maxlength="150" value="${esc(selected.english_title)}"></label><label>页面短名<input name="slug" pattern="[a-z0-9]+(-[a-z0-9]+)*" required value="${esc(selected.slug)}" placeholder="例如 bodyweight-squat"></label><label>内容类型<select name="content_type">${[['exercise','动作资料'],['guide','训练指南'],['workout-template','训练模板']].map(([id,name])=>`<option value="${id}" ${selected.content_type===id?'selected':''}>${name}</option>`).join('')}</select></label></div><label>简介<textarea name="summary" maxlength="2000">${esc(selected.summary)}</textarea></label><label>搜索别名（用逗号分隔）<input name="aliases" value="${esc((selected.aliases??[]).join(', '))}"></label><div class="workspace-two"><label>内容审核状态<select name="review_status">${[['prototype','样本 · 待专业审核'],['needs-review','待审核'],['reviewed','已审核']].map(([id,name])=>`<option value="${id}" ${selected.review_status===id?'selected':''}>${name}</option>`).join('')}</select></label><label>展示顺序<input name="display_order" type="number" step="1" value="${esc(selected.display_order)}"></label></div><fieldset><legend>主题与分区</legend>${THEMES.map(theme=>`<div><strong class="workspace-small">${esc(theme.name)}</strong> ${checkboxGroup('theme:'+theme.id,theme.sections,selected.theme_links.find(x=>x.theme===theme.id)?.sections)}</div>`).join('')}</fieldset><fieldset><legend>运动项目</legend>${checkboxGroup('discipline_ids',FILTERS.disciplines.options,selected.discipline_ids)}</fieldset><fieldset><legend>器械</legend>${checkboxGroup('equipment_ids',FILTERS.equipment.options,selected.equipment_ids)}</fieldset><fieldset><legend>主要肌群</legend>${checkboxGroup('primary_muscle_ids',FILTERS.muscles.options,selected.primary_muscle_ids)}</fieldset><label>观察要点（一行一个）<textarea name="focus">${esc((selected.details.focus??selected.details.motion?.focus??[]).join('\n'))}</textarea></label><label>内容说明<textarea name="body" maxlength="20000">${esc(selected.details.sections?.map(x=>x.body).join('\n\n')??'')}</textarea></label><div class="workspace-actions"><button class="button primary" type="submit" ${busy?'disabled':''}>保存${isNew?'草稿':'修改'}</button><button class="button outline" type="button" data-action="publish" ${busy?'disabled':''}>保存并发布</button>${!isNew?'<button class="button outline" type="button" data-action="unpublish">转为草稿</button><button class="button outline" type="button" data-action="archive">下架</button>':''}</div></form><h3 class="workspace-section-label">示范媒体</h3><div class="workspace-media-list">${selected.media?.length?selected.media.map(m=>`<a href="${esc(m.url??'#')}" target="_blank" rel="noopener noreferrer">${esc(m.kind)} · ${(m.byte_size/1024/1024).toFixed(2)} MB ↗</a>`).join(''):'<p>尚未上传媒体。</p>'}</div><form id="upload-form"><div class="workspace-two"><label>媒体类型<select id="media-kind"><option value="model">3D 模型（GLB）</option><option value="gif">动图（GIF）</option><option value="image">封面图片</option><option value="video">示范视频</option></select></label><label>选择文件<input id="media-file" type="file" accept=".glb" required></label></div><p class="workspace-small">单个文件不超过 20 MB。文件存入后台存储；只有已发布内容的媒体可以被公开读取。</p><button class="button outline" type="submit" ${isNew||busy?'disabled':''}>上传并关联媒体</button>${isNew?'<p class="workspace-small">请先保存草稿，再上传媒体。</p>':''}</form></section>`;}
function render(){
  const tabs=`<nav class="workspace-tabs" aria-label="管理分类">${[['content','教程与媒体'],['users','账号与权限'],['activity','访问与操作记录']].map(([id,name])=>`<button data-section="${id}" class="${section===id?'selected':''}">${name}</button>`).join('')}</nav>`;
  if(section==='content')root.innerHTML=tabs+`<div class="workspace-grid"><aside class="workspace-card"><div class="workspace-row"><h3>全部内容</h3><button class="workspace-icon-button" data-action="new">＋ 新建</button></div><div class="workspace-list" style="margin-top:16px">${contents.map(item=>`<button data-action="select" data-id="${esc(item.id)}" class="${selected?.id===item.id?'selected':''}">${esc(item.title)}<small>${statusLabel[item.publication_status]} · 第 ${item.revision} 版</small></button>`).join('')||'<p>还没有内容。</p>'}</div></aside>${contentEditor()}</div>`;
  if(section==='users')root.innerHTML=tabs+`<section class="workspace-card"><h2>账号与权限</h2><p>管理员可维护公开内容、调整角色和停用账号；不会因此取得其他用户私人计划的读取权限。</p><div class="workspace-overflow"><table class="workspace-table"><thead><tr><th>账号</th><th>角色</th><th>状态</th><th>操作</th></tr></thead><tbody>${users.map(user=>`<tr><td>${esc(user.display_name)}<br><span class="muted">${esc(user.email)}</span></td><td><select data-user-role="${esc(user.id)}" aria-label="调整 ${esc(user.display_name||user.email)} 的角色"><option value="member" ${user.role==='member'?'selected':''}>普通用户</option><option value="admin" ${user.role==='admin'?'selected':''}>管理员</option></select></td><td>${user.account_status==='active'?'正常':'已停用'}</td><td><button class="workspace-icon-button" data-action="account-status" data-id="${esc(user.id)}" data-status="${user.account_status==='active'?'suspended':'active'}">${user.account_status==='active'?'停用':'恢复'}</button></td></tr>`).join('')}</tbody></table></div></section>`;
  if(section==='activity')root.innerHTML=tabs+`<section class="workspace-card"><div class="workspace-row"><h2>已登录用户活动</h2><span class="workspace-pill">近 30 天 ${Number(activity?.last_30_days??0)} 条</span></div><p>用于查看登录后页面访问与内容浏览，不记录私人计划正文；这些活动统计与权限审计分别保存。</p><div class="workspace-overflow"><table class="workspace-table"><thead><tr><th>时间</th><th>用户</th><th>事件</th><th>页面</th></tr></thead><tbody>${(activity?.recent??[]).map(e=>`<tr><td>${new Date(e.created_at).toLocaleString('zh-CN')}</td><td>${esc(e.display_name)}</td><td>${esc(e.event_type)}</td><td>${esc(e.path)}</td></tr>`).join('')||'<tr><td colspan="4">尚无记录。</td></tr>'}</tbody></table></div></section><section class="workspace-card"><h2>管理操作审计</h2><div class="workspace-overflow"><table class="workspace-table"><thead><tr><th>时间</th><th>操作</th><th>对象</th></tr></thead><tbody>${(activity?.audit??[]).map(e=>`<tr><td>${new Date(e.created_at).toLocaleString('zh-CN')}</td><td>${esc(e.action)}</td><td>${esc(e.object_id)}</td></tr>`).join('')||'<tr><td colspan="3">尚无记录。</td></tr>'}</tbody></table></div></section>`;
}
function readForm(){const form=new FormData(root.querySelector('#content-form'));const text=key=>String(form.get(key)??'').trim();const details={...selected.details,focus:text('focus').split('\n').map(x=>x.trim()).filter(Boolean),sections:text('body')?[{heading:'内容说明',body:text('body')}]:[]};if(details.motion)details.motion={...details.motion,focus:details.focus};return {...selected,title:text('title'),english_title:text('english_title'),slug:text('slug'),content_type:text('content_type'),summary:text('summary'),aliases:text('aliases').split(/[,，]/).map(x=>x.trim()).filter(Boolean),review_status:text('review_status'),display_order:Number(form.get('display_order')),theme_links:THEMES.map(t=>({theme:t.id,sections:form.getAll('theme:'+t.id)})).filter(t=>t.sections.length),discipline_ids:form.getAll('discipline_ids'),equipment_ids:form.getAll('equipment_ids'),primary_muscle_ids:form.getAll('primary_muscle_ids'),details};}
async function reloadContent(id=selected?.id){contents=await api.adminContents();if(id)selected=contents.find(x=>x.id===id)??null;isNew=false;render();}
async function saveContent(){const values=readForm();if(!root.querySelector('#content-form').reportValidity())return null;const saved=await api.adminSaveContent(values,isNew);await reloadContent(saved.id);return saved;}
async function loadSection(){if(section==='content')await reloadContent();if(section==='users'){users=await api.adminUsers();render();}if(section==='activity'){activity=await api.adminActivity();render();}}
root.addEventListener('click',async event=>{const button=event.target.closest('[data-action],[data-section]');if(!button||busy)return;try{if(button.dataset.section){section=button.dataset.section;await loadSection();return;}const a=button.dataset.action;if(a==='new'){selected=draft();isNew=true;render();return;}if(a==='select'){selected=structuredClone(contents.find(x=>x.id===button.dataset.id));isNew=false;render();return;}if(a==='publish'){busy=true;const saved=await saveContent();if(saved){await api.adminPublish(saved.id,'published');await reloadContent(saved.id);status('内容已发布，公开页面会读取发布结果。');}}if(a==='unpublish'||a==='archive'){await api.adminPublish(selected.id,a==='archive'?'archived':'draft');await reloadContent();status(a==='archive'?'内容已下架。':'内容已转为草稿。');}if(a==='account-status'){if(!confirm(button.dataset.status==='suspended'?'停用这个账号？其私人数据将保留，但账号将失去受保护功能的访问权限。':'恢复这个账号？'))return;await api.adminSetAccountStatus(button.dataset.id,button.dataset.status);await loadSection();status('账号状态已更新。');}}catch(error){status(error.message,true);}finally{busy=false;render();}});
root.addEventListener('change',async event=>{try{if(event.target.id==='media-kind'){root.querySelector('#media-file').accept={model:'.glb',gif:'.gif',image:'.png,.jpg,.jpeg,.webp',video:'.mp4,.webm'}[event.target.value];root.querySelector('#media-file').value='';}if(event.target.dataset.userRole){if(!confirm('确认调整这个账号的角色？')){await loadSection();return;}await api.adminSetRole(event.target.dataset.userRole,event.target.value);await loadSection();status('角色已更新。');}}catch(error){status(error.message,true);await loadSection();}});
root.addEventListener('submit',async event=>{event.preventDefault();if(busy)return;busy=true;try{if(event.target.id==='content-form'){await saveContent();status('内容已保存。');}if(event.target.id==='upload-form'){const file=root.querySelector('#media-file').files[0];if(!file)throw new Error('请先选择媒体文件');status('正在上传媒体，请稍候…');await api.adminUpload(selected,file,root.querySelector('#media-kind').value);await reloadContent();status('媒体已保存并关联到此内容。');}}catch(error){status(error.message,true);}finally{busy=false;render();}});
try{await api.initializeBackend();identity=api.currentIdentity();if(!identity.user||identity.access?.role!=='admin'||identity.access?.account_status!=='active'){root.innerHTML='<section class="workspace-card"><h2>需要管理员账号</h2><p>请先登录拥有管理权限的网站账号。</p><a class="button primary" href="/account/index.html">前往我的账号 ↗</a></section>';}else{await loadSection();api.recordActivity('page_view','/admin');api.subscribeIdentity(next=>{if(next.user?.id!==identity.user?.id||next.access?.role!=='admin')location.reload();});}}catch(error){root.innerHTML=`<section class="workspace-card"><h2>管理服务暂不可用</h2><p class="workspace-error">${esc(error.message)}</p><a class="button outline" href="/account/index.html">返回我的账号</a></section>`;}
